const message = $json.message ?? {};
const text = String(message.text ?? '').trim();
const chatId = String(message.chat?.id ?? '').trim();
const messageId = String(message.message_id ?? '').trim();
if (!chatId) throw new Error('Telegram chat ID is missing');
const cleaned = text.replace(/^\/submit(?:@\w+)?\s*/i, '').trim();
const urlMatch = cleaned.match(/https?:\/\/[^\s<>]+/i);
if (!urlMatch) return [{ json: { valid: false, chatId, messageId, help: 'Send: Title | https://example.com/post\nOr use three lines: title, URL, optional notes.' } }];
const url = urlMatch[0].replace(/[),.;]+$/, '');
const before = cleaned.slice(0, urlMatch.index).trim().replace(/[|\n:-]+$/g, '').trim();
const after = cleaned.slice((urlMatch.index ?? 0) + urlMatch[0].length).trim().replace(/^[|\n:-]+/g, '').trim();
const title = before || after.split(/\r?\n/)[0]?.trim() || '';
const notes = before ? after : after.split(/\r?\n/).slice(1).join('\n').trim();
if (!title) return [{ json: { valid: false, chatId, messageId, help: 'A title is required. Send: Title | https://example.com/post' } }];
return [{ json: { valid: true, chatId, messageId, title: title.slice(0, 240), url, notes: notes.slice(0, 5000) } }];

